import json, urllib.request

# P1a: PyPI JSON API — can we get version history with dates?
for pkg in ['django', 'requests', 'flask']:
    url = 'https://pypi.org/pypi/%s/json' % pkg
    req = urllib.request.Request(url, headers={'User-Agent': 'think-free-e179/1.0'})
    try:
        with urllib.request.urlopen(req, timeout=30) as fh:
            data = json.load(fh)
        releases = data.get('releases', {})
        versions = sorted(releases.keys())
        sample = {}
        for v in [versions[0], versions[len(versions)//2], versions[-1]]:
            files = releases.get(v, [])
            if files:
                sample[v] = files[0].get('upload_time', 'unknown')
        print('PYPI %s: %d versions, first=%s last=%s' % (pkg, len(versions), versions[0], versions[-1]))
        print('  sample dates: %s' % sample)
    except Exception as e:
        print('PYPI %s: FAILED %s' % (pkg, e))
